<script>
 import { t } from '$lib/assets/translations';
  import {page} from '$app/stores';export let json={};$:current=Number(json?.current||1);$:limit=Math.max(1,Math.min(Math.ceil((json?.total||1)/(json?.fetch||1)),Math.floor(500/(json?.fetch||1))));$:pages=Array.from({length:Math.min(5,limit)},(_,i)=>Math.max(1,Math.min(limit,current-2+i)));function href(n){const url=new URL($page.url);url.searchParams.set('page',n);return url.pathname+url.search}
</script>
{#if limit>1}<nav class="pager" aria-label={$t("Pages")}><a class:disabled={current===1} href={href(1)}>«<span>{$t("First")}</span></a><a class:disabled={current===1} href={href(Math.max(1,current-1))}>‹</a>{#each [...new Set(pages)] as number}<a class:active={number===current} href={number===current?null:href(number)}>{number}</a>{/each}<a class:disabled={current===limit} href={href(Math.min(limit,current+1))}>›</a><a class:disabled={current===limit} href={href(limit)}><span>{$t("Last")}</span>»</a></nav>{/if}
<style>.pager{display:flex;justify-content:center;align-items:center;gap:6px;margin:30px auto 0;max-width:100%;overflow-x:auto}.pager a{display:flex;align-items:center;gap:5px;justify-content:center;min-width:38px;height:38px;padding:0 10px;border:1px solid var(--line);border-radius:10px;background:var(--panel);color:var(--muted);text-decoration:none;font-weight:800}.pager a:hover,.pager a.active{border-color:var(--gold);color:var(--gold);background:#211b10}.pager a.disabled{opacity:.3;pointer-events:none}@media(max-width:550px){.pager a span{display:none}.pager a{min-width:34px;height:34px;padding:0 8px}}</style>
